static int worker(int argc,WCHAR **argv){(void)argc;(void)argv;WNDCLASSW wc={0};wc.hInstance=GetModuleHandleW(NULL);wc.lpfnWndProc=parent;wc.lpszClassName=L"CanonTransitionProbe";if(!RegisterClassW(&wc))return 2;HWND root=CreateWindowW(wc.lpszClassName,L"probe",WS_OVERLAPPEDWINDOW,10,10,220,140,NULL,NULL,wc.hInstance,NULL);HWND child=CreateWindowW(L"BUTTON",L"",WS_CHILD|WS_VISIBLE|BS_PUSHBUTTON,10,10,80,60,root,(HMENU)1,wc.hInstance,NULL);if(!root||!child)return 3;ShowWindow(root,SW_SHOWNA);RedrawWindow(root,NULL,NULL,RDW_INVALIDATE|RDW_ALLCHILDREN|RDW_UPDATENOW);HMODULE mod=GetModuleHandleW(sizeof(void*)==8?L"ntw16s64.dll":L"ntw16s32.dll");BOOL(__cdecl *attached)(HWND)=mod?(void*)GetProcAddress(mod,"Ntw16sWindowAttached"):NULL;int before=attached?attached(child):0;LONG_PTR old=GetWindowLongPtrW(child,GWL_STYLE);SetWindowLongPtrW(child,GWL_STYLE,(old&~BS_TYPEMASK)|BS_OWNERDRAW);RedrawWindow(child,NULL,NULL,RDW_INVALIDATE|RDW_UPDATENOW);int after=attached?attached(child):0;calls=0;HDC dc=CreateCompatibleDC(NULL);BITMAPINFO b={0};b.bmiHeader.biSize=sizeof(b.bmiHeader);b.bmiHeader.biWidth=80;b.bmiHeader.biHeight=-60;b.bmiHeader.biPlanes=1;b.bmiHeader.biBitCount=32;DWORD *bits=NULL;HBITMAP bm=CreateDIBSection(dc,&b,DIB_RGB_COLORS,(void**)&bits,NULL,0);if(!dc||!bm||!bits)return 4;HGDIOBJ save=SelectObject(dc,bm);SendMessageW(child,WM_PRINTCLIENT,(WPARAM)dc,PRF_CLIENT|PRF_ERASEBKGND);GdiFlush();unsigned pixels=0;for(int i=0;i<80*60;i++)if((bits[i]&0xffffff)==0xff00ff)++pixels;printf("OWNERDRAW_TRANSITION styled=%d before=%d after=%d style=%08lx drawitem=%u pixels=%u\n",mod!=NULL,before,after,(DWORD)GetWindowLongPtrW(child,GWL_STYLE),calls,pixels);
    BOOL passed=mod && attached && before && !after && calls==1 && pixels==4800;SelectObject(dc,save);DeleteObject(bm);DeleteDC(dc);DestroyWindow(root);UnregisterClassW(wc.lpszClassName,wc.hInstance);if(!passed){fprintf(stderr,"OWNERDRAW_TRANSITION_FAIL\n");return 1;}puts("OWNERDRAW_TRANSITION_PASS");return 0;}
